      await press('keyUp', ' ');
      await sleep(200);
      await press('keyDown', ' ');
    }
    if (Date.now() - lastJitter > 1600) {
      lastJitter = Date.now();
      await press('keyUp', dir);
      dir = dir === 'ArrowLeft' ? 'ArrowRight' : 'ArrowLeft';
      if (Math.random() < 0.15) dir = 'ArrowDown';
      await press('keyDown', dir);
      await sleep(500);
      if (dir === 'ArrowDown') { await press('keyUp', dir); dir = 'ArrowLeft'; await press('keyDown', dir); }
    }
    await sleep(500);
