// ------------------------------------------------------------- boot

async function boot() {
  const glb1 = await new GLB('data/FILE0001.GLB').load();
  const glb0 = await new GLB('data/FILE0000.GLB').load();
  sound = new Sound(glb0);
  game = new Game(glb1, glb0, sound);

  const r = window.__raptor;
  r.wave = game.wave + 1;

  let acc = 0;
  let last = performance.now();
  let lastState = game.state;

  function tick(now) {
    acc += now - last;
    last = now;
    if (acc > 200) acc = 200; // tab was hidden: don't fast-forward

    while (acc >= FRAME_MS) {
      acc -= FRAME_MS;
      if (game.state === 'playing') game.frame();
      if (game.state !== lastState) {
        lastState = game.state;
        if (game.state !== 'playing') game.drawEndScreen();
      }
    }

    present();
    game.syncRaptor(window.__raptor);
    requestAnimationFrame(tick);
  }

  requestAnimationFrame(tick);
}

boot().catch((err) => {
  console.error('Raptor boot failed:', err);

