details.oldText:
// main.mjs -- boot, input, render loop, window.__raptor grader contract.
//
// The original DOS game runs a ~50 FPS vblank-synced loop; the whole game
// logic is tuned to that cadence, so we tick Game.frame() at 50 Hz and let
// requestAnimationFrame drive presentation.

import { GLB } from './glb.mjs';
import { Game } from './game.mjs';
import { Sound } from './audio.mjs';

const W = 320, H = 200, FRAME_MS = 20; // 50 Hz

const canvas = document.getElementById('raptor-canvas');
const ctx = canvas.getContext('2d', { alpha: false });
const img = ctx.createImageData(W, H);
const lut = new Uint8ClampedArray(256 * 4);

window.__raptor = {
  ready: false,
  player: { x: 0, y: 0, alive: false },
  projectiles: [],
  enemies: [],
  hud: { score: 0, shields: 0 },
  audio: { contextState: 'suspended', sfxCount: 0 },
  wave: 0,
  sectorComplete: false,
};

let game = null;
let sound = null;

// ------------------------------------------------------------- input

const KEYMAP = {
  ArrowLeft: 'left',
  ArrowRight: 'right',
  ArrowUp: 'up',
  ArrowDown: 'down',
  ' ': 'fire',
};

function unlockAudio() {
  if (sound) sound.ensure();
}

window.addEventListener('keydown', (ev) => {
  if (!game) return;
  const k = KEYMAP[ev.key];
  if (k) {
    ev.preventDefault();
    unlockAudio();
    if (k === 'fire' && game.state !== 'playing') {
      game.keyRestart();
    }
    if (game.state === 'playing') game.input[k] = true;
  }
});

window.addEventListener('keyup', (ev) => {
  if (!game) return;
  const k = KEYMAP[ev.key];
  if (k) {
    ev.preventDefault();
    game.input[k] = false;
  }
});

window.addEventListener('mousedown', unlockAudio);

// ------------------------------------------------------------- render

function present() {
  const pal = game.gpal;
  for (let c = 0; c < 256; c++) {
    const l = c * 4, p = c * 3;
    lut[l] = pal[p];
    lut[l + 1] = pal[p + 1];
    lut[l + 2] = pal[p + 2];
    lut[l + 3] = 255;
  }
  const px = game.px;
  const d = img.data;
  for (let i = 0; i < W * H; i++) {
    const l = px[i] << 2;
    const o = i << 2;
    d[o] = lut[l];
    d[o + 1] = lut[l + 1];
