// temp M5 contract browser check (deleted after run)
// Phase A: real gameplay autoplay, __raptor.wave must advance live (1 -> 3+).
// Phase B: force the wave-9 end via the debug handle, verify sectorComplete
//          flip + complete screen paint. (Full natural sector completion is
//          covered by test/smoke.mjs, 18/18.)
import { spawn } from 'node:child_process';
import path from 'node:path';
import os from 'node:os';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

const PORT = 8765;

function findChrome() {
  const env = process.platform === 'win32'
    ? (process.env.LOCALAPPDATA || path.join(os.homedir(), 'AppData', 'Local'))
    : (process.env.HOME || os.homedir());
  const base = path.join(env, 'ms-playwright');
  if (!fs.existsSync(base)) return null;
  const dirs = fs.readdirSync(base)
    .filter((d) => d.startsWith('chromium-') && !d.includes('headless_shell'))
    .sort().reverse();
  for (const d of dirs) {
    for (const sub of ['chrome-win64', 'chrome-linux', 'chrome-mac']) {
      const exe = path.join(base, d, sub, process.platform === 'win32' ? 'chrome.exe' : 'chrome');
      if (fs.existsSync(exe)) return exe;
    }
  }
  return null;
}
const chrome = findChrome();
if (!chrome) { console.error('no bundled chromium found under ms-playwright'); process.exit(2); }

const dbgPort = 9333 + Math.floor(Math.random() * 100);
const profile = fs.mkdtempSync(path.join(os.tmpdir(), 'raptor-cdp-'));
const chromeLog = path.join(os.tmpdir(), 'raptor-cdp-chrome.log');
const logStream = fs.createWriteStream(chromeLog);
const chromeProc = spawn(chrome, [
  `--remote-debugging-port=${dbgPort}`,
  `--user-data-dir=${profile}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check',
  'about:blank',
], { stdio: ['ignore', 'pipe', 'pipe'] });
chromeProc.stderr.pipe(logStream);
chromeProc.stdout.resume();

let failures = 0;
function check(cond, msg) {
  if (!cond) failures++;
  console.log((cond ? 'ok  : ' : 'FAIL: ') + msg);
}
async function getJson(url, method = 'GET') {
  const r = await fetch(url, { method });
  return r.json();
}
async function waitForDebugger() {
  for (let i = 0; i < 50; i++) {
    try {
      const l = await getJson(`http://127.0.0.1:${dbgPort}/json/list`);
      if (Array.isArray(l) && l.length) return;
    } catch { /* not up yet */ }
    await new Promise((r) => setTimeout(r, 200));
  }
  throw new Error('chrome debugger not reachable');
}
class CDP {
  constructor(ws) { this.ws = ws; this.id = 0; this.pending = new Map(); this.dead = false; }
  static async connect(url) {
    const ws = new WebSocket(url);
    await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
    const c = new CDP(ws);
    ws.onmessage = (m) => {
      const msg = JSON.parse(m.data);
      if (msg.id && c.pending.has(msg.id)) {
        const { res, rej } = c.pending.get(msg.id);
        c.pending.delete(msg.id);
        msg.error ? rej(new Error(msg.error.message)) : res(msg.result);
      }
    };
    ws.onclose = () => { c.dead = true; for (const { rej } of c.pending.values()) rej(new Error('CDP connection closed')); c.pending.clear(); };
    ws.onerror = () => { if (c.dead) return; c.dead = true; for (const { rej } of c.pending.values()) rej(new Error('CDP socket error')); c.pending.clear(); };
    return c;
  }
  send(method, params = {}) {
    if (this.dead) return Promise.reject(new Error('CDP closed'));
    const id = ++this.id;
    this.ws.send(JSON.stringify({ id, method, params }));
    return new Promise((res, rej) => this.pending.set(id, { res, rej }));
  }
  close() { try { this.ws.close(); } catch { /* ignore */ } }
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function die(msg) {
  console.error(msg);
  try { console.error('--- chrome stderr tail ---\n' + fs.readFileSync(chromeLog, 'utf8').slice(-4000)); } catch { /* no log */ }
let cdp = null;
try {

try {
  cdp = await CDP.connect(target.webSocketDebuggerUrl);
  const target = await getJson(`http://127.0.0.1:${dbgPort}/json/new?about:blank`, 'PUT');
  const cdp = await CDP.connect(target.webSocketDebuggerUrl);
  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');
  const evalJs = async (expr) => {
    const r = await cdp.send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error('page exception: ' + JSON.stringify(r.exceptionDetails).slice(0, 500));
    return r.result.value;
  };

  await cdp.send('Page.navigate', { url: `http://127.0.0.1:${PORT}/` });
  let ready = false;
  for (let i = 0; i < 120; i++) {
    ready = await evalJs(`window.__raptor && window.__raptor.ready === true`).catch(() => false);
    if (ready) break;
    await sleep(250);
  }
  check(ready, 'booted, ready true');
  if (!ready) throw new Error('boot failed');
  check(await evalJs(`window.__raptorGame !== undefined`), 'debug handle __raptorGame present');

  const press = (type, key) => cdp.send('Input.dispatchKeyEvent', {
    type, key, code: key === ' ' ? 'Space' : key,
    windowsVirtualKeyCode: key === ' ' ? 32 : { ArrowLeft: 37, ArrowRight: 39, ArrowUp: 38, ArrowDown: 40 }[key],
  });

  // == Phase A: real gameplay, wave counter advances live ==
  await press('keyDown', ' ');
  const waves = [1];
  let lastWave = 1, complete = false, t0 = Date.now(), lastJitter = 0, dir = 'ArrowLeft';
  const PHASE_A_MS = 5 * 60 * 1000;
  while (Date.now() - t0 < PHASE_A_MS && !complete && lastWave < 3) {
    const r = await evalJs(`JSON.parse(JSON.stringify(window.__raptor))`);
    if (r.wave !== lastWave) {
      lastWave = r.wave;
      waves.push(r.wave);
      console.log(`      wave ${r.wave} at +${((Date.now() - t0) / 1000) | 0}s`);
    }
    complete = r.sectorComplete === true;
    if (!r.player.alive) {
      await press('keyUp', ' ');
      await sleep(200);
      await press('keyDown', ' ');
    }
    if (Date.now() - lastJitter > 1600) {
      lastJitter = Date.now();
      await press('keyUp', dir);
      dir = dir === 'ArrowLeft' ? 'ArrowRight' : 'ArrowLeft';
      await press('keyDown', dir);
      await sleep(500);
    }
    await sleep(500);
  }
  await press('keyUp', ' ');
  await press('keyUp', 'ArrowLeft'); await press('keyUp', 'ArrowRight');
  const phaseA = ((Date.now() - t0) / 1000) | 0;
  check(lastWave >= 3, `__raptor.wave advanced live through real play (sequence ${waves.join(',')} in ${phaseA}s)`);
  check(!complete, 'sectorComplete still false mid-sector');

  // == Phase B: force wave-9 end via debug handle ==
  await evalJs(`(() => {
    const g = window.__raptorGame;
    g.wave = 8;                    // index of wave 9
    g.enemies.length = 0;
    g.eshots.length = 0;
    g.startendwave = 1;            // counts to 0 next frame -> finishWave()
    return true;
  })()`);
  let completeNow = false, t1 = Date.now();
  while (Date.now() - t1 < 15000 && !completeNow) {
    completeNow = await evalJs(`window.__raptor.sectorComplete === true`);
    await sleep(250);
  }
  check(completeNow, `sectorComplete flipped true at wave-9 end (+${((Date.now() - t1) / 1000).toFixed(1)}s)`);
  const final = await evalJs(`JSON.parse(JSON.stringify(window.__raptor))`);
  check(final.wave === 9, `__raptor.wave is 9 at completion (${final.wave})`);
  check(final.sectorComplete === true, 'final sectorComplete true');

  await sleep(300); // let the end screen paint
  const scr = await evalJs(`(() => {
    const d = document.getElementById('raptor-canvas').getContext('2d').getImageData(0,0,320,200).data;
    let n = 0, totalN = 0;
    for (let y = 0; y < 200; y++) for (let x = 0; x < 320; x++) {
      const o = (y * 320 + x) * 4;
      if (d[o] | d[o+1] | d[o+2]) totalN++;
      if (y >= 68 && y < 80 && x >= 88 && x < 232 && (d[o] | d[o+1] | d[o+2])) n++;
    }
    return { n, totalN };
  })()`);
  check(scr.totalN < 20000, `complete screen replaced playfield (non-black ${scr.totalN}/64000 px; playfield is ~46k)`);
  check(scr.n > 60, `sector-complete title painted (band y68-80: ${scr.n} px)`);
  const scoreBandPx = await evalJs(`(() => {
    const d = document.getElementById('raptor-canvas').getContext('2d').getImageData(0,0,320,200).data;
    let n = 0;
    for (let y = 88; y < 100; y++) for (let x = 48; x < 272; x++) {
      const o = (y * 320 + x) * 4;
      if (d[o] | d[o+1] | d[o+2]) n++;
    }
    return n;
  })()`);
  check(scoreBandPx > 60, `complete screen shows score line (${scoreBandPx} px at y88-100)`);
  check(final.hud.score > 10000, `score accumulated during phase A (${final.hud.score})`);

  const { data } = await cdp.send('Page.captureScreenshot', { format: 'png' });
  const out = path.resolve('tools/m5-complete.png');
  fs.writeFileSync(out, Buffer.from(data, 'base64'));
  console.log('      screenshot:', out);

  cdp.close();
} catch (e) {
  die('M5 browser check crashed: ' + (e && e.message ? e.message : e) + '\n' + (e && e.stack ? e.stack.split('\n').slice(0, 5).join('\n') : ''));
} finally {
  try { cdp.close(); } catch { /* ignore */ }
  chromeProc.kill();
  try { fs.rmSync(profile, { recursive: true, force: true }); } catch { /* ignore */ }
  try { logStream.end(); } catch { /* ignore */ }
}
console.log(failures ? 'M5 BROWSER CHECK FAILED' : 'M5 BROWSER CHECK OK');
process.exit(failures ? 1 : 0);

