check(sfxLog.length >= 1, `gun SFX triggered (${sfxLog.length})`);

// --- M3: enemies spawn over time; projectiles can kill ---
let seenEnemy = false, sawHpDrop = false, maxEnemies = 0;
for (let i = 0; i < 50 * 60; i++) { … }
