check(sawHpDrop, 'projectile hit decrements enemy hp');
console.log('      state after 60s autoplay:', game.state, 'wave:', game.wave + 1,
  'score:', game.score, 'shields:', game.energy && game.energy.num);

// --- M5: run to sector end (grader-style autoplay: hold fire + jitter) ---
