// game.mjs -- faithful HTML5 port of Raptor: Call of the Shadows, sector 1.
//
// One-to-one port of the Do_Game() frame pipeline (SOURCE/RAP.C) and the
// TILE / ENEMY / ESHOT / SHOTS / BONUS / ANIMS / OBJS / SHADOW subsystems.
// All constants, formulas, and ordering match the GPL C source; comments cite
// the source function each block ports.

import { GLB } from './glb.mjs';
import { decodePic, blitPic } from './pic.mjs';
import { FX, Sound } from './audio.mjs';

// ------------------------------------------------------------ constants

// MAP.H
const MAP_ROWS = 150, MAP_ONSCREEN = 8, MAP_COLS = 9, MAP_BLOCKSIZE = 32;
const MAP_BOTTOM = 200 - 18, MAP_TOP = 2, MAP_LEFT = 16, MAP_RIGHT = 320 - 16;
const MAP_SIZE = MAP_ROWS * MAP_COLS;
const MAX_GUNS = 24, MAX_FLIGHT = 30;

// PUBLIC.H / RAPTOR.H
const SHIELD_COLOR_RUN = 9, SHIELD_LOW = 10;
const PLAYERWIDTH = 32, PLAYERHEIGHT = 32;
const PLAYERMINX = 5, PLAYERMAXX = 314;
const PLAYERINITX = 160 - (PLAYERWIDTH / 2), PLAYERINITY = 160;
const MINPLAYERY = 0, MAXPLAYERY = 160;
const MAX_SHIELD = 100, CHARGE_SHIELD = 24 * 4, TRAINING_INV = 120;
const EMPTY = -1; // C INT 0xFFFFFFFF
const END_DURATION = 20 * 3, END_EXPLODE = 24, END_FLYOFF = 20 * 2;
const DIFF_0 = 0, DIFF_1 = 1, DIFF_2 = 2, DIFF_3 = 3;
const MAX_GAME_WAVES = 9; // diff_wrap[DIFF_2]

// MAP.H enums
const E_SECRET_1 = 0, E_SECRET_2 = 1, E_SECRET_3 = 2, E_EASY_LEVEL = 3,
  E_MED_LEVEL = 4, E_HARD_LEVEL = 5;
const EB_SECRET_1 = 1, EB_SECRET_2 = 2, EB_SECRET_3 = 4, EB_EASY_LEVEL = 8,
  EB_MED_LEVEL = 16, EB_HARD_LEVEL = 32, EB_NOT_USED = 64;
const F_REPEAT = 0, F_LINEAR = 1, F_KAMI = 2, F_GROUND = 3,
  F_GROUNDLEFT = 4, F_GROUNDRIGHT = 5;
const GANIM_NORM = 0, GANIM_SHOOT = 1, GANIM_MULTI = 2;
const KAMI_FLY = 0, KAMI_CHASE = 1, KAMI_END = 2;
const MULTI_OFF = 0, MULTI_START = 1, MULTI_END = 2;
const NORM_SHOOT = -1, START_SHOOT = 0;
const E_FORWARD = 0, E_BACKWARD = 1;
const GROUND = 0, MID_AIR = 1, HIGH_AIR = 2;
const A_NORM = 0, A_MOVEUP = 1, A_MOVEDOWN = 2;

// MAP.H EXP_TYPE
const EXP_AIRSMALL1 = 0, EXP_AIRMED = 1, EXP_AIRLARGE = 2, EXP_GRDSMALL = 3,
  EXP_GRDMED = 4, EXP_GRDLARGE = 5, EXP_BOSS = 6, EXP_PERSON = 7,
  EXP_ENERGY = 8, EXP_PLATOON = 9, EXP_AIRSMALL2 = 10;

// ANIMS.H handles
const A_LARGE_GROUND_EXPLO1 = 0, A_SMALL_GROUND_EXPLO = 1, A_PERSON = 2,
  A_PLATOON = 3, A_LARGE_AIR_EXPLO = 4, A_MED_AIR_EXPLO = 5,
  A_SMALL_AIR_EXPLO = 6, A_MED_AIR_EXPLO2 = 7, A_ENERGY_AIR_EXPLO = 8,
  A_LASER_BLAST = 9, A_SMALL_SMOKE = 10, A_SMALL_SMOKE_DOWN = 11,
  A_SMALL_SMOKE_UP = 12, A_ENERGY_GRAB_HIT = 13, A_BLUE_SPARK = 14,
  A_ORANGE_SPARK = 15, A_PLAYER_SHOOT = 16, A_GROUND_FLARE = 17,
  A_GROUND_SPARKLE = 18, A_ENERGY_GRAB = 19, A_SUPER_SHIELD = 20;

// ESHOT.H
const ES_ATPLAYER = 0, ES_ATDOWN = 1, ES_ANGLELEFT = 2, ES_ANGLERIGHT = 3,
  ES_MISSLE = 4, ES_MINES = 5, ES_LASER = 6, ES_PLASMA = 7;

// OBJECTS.H
const S_FORWARD_GUNS = 0, S_ENERGY = 13, S_ITEMBUY6 = 19, S_SUPER_SHIELD = 0;
const SPRITE_SIZE = 528;

// RAP.C
