// main.mjs -- boot, input, render loop, window.__raptor grader contract.
//
// The original DOS game runs a ~50 FPS vblank-synced loop; the whole game
// logic is tuned to that cadence, so we tick Game.frame() at 50 Hz and let
// requestAnimationFrame drive presentation.

import { GLB } from './glb.mjs';
import { Game } from './game.mjs';
import { Sound } from './audio.mjs';

const W = 320, H = 200, FRAME_MS = 20; // 50 Hz

const canvas = document.getElementById('raptor-canvas');
const ctx = canvas.getContext('2d', { alpha: false });
const img = ctx.createImageData(W, H);
const lut = new Uint8ClampedArray(256 * 4);

window.__raptor = {
  ready: false,
  player: { x: 0, y: 0, alive: false },
  projectiles: [],
  enemies: [],
  hud: { score: 0, shields: 0 },
  audio: { contextState: 'suspended', sfxCount: 0 },
  wave: 0,
  sectorComplete: false,
};

let game = null;
let sound = null;

// ------------------------------------------------------------- input

const KEYMAP = {
  ArrowLeft: 'left',
  ArrowRight: 'right',
  ArrowUp: 'up',
  ArrowDown: 'down',
  ' ': 'fire',
};

function unlockAudio() {
  if (sound) sound.ensure();
}

window.addEventListener('keydown', (ev) => {
  if (!game) return;
  const k = KEYMAP[ev.key];
  if (k) {
    ev.preventDefault();
    unlockAudio();
    if (k === 'fire' && game.state !== 'playing') {
      game.keyRestart();
    }
    if (game.state === 'playing') game.input[k] = true;
  }
});

window.addEventListener('keyup', (ev) => {
  if (!game) return;
  const k = KEYMAP[ev.key];
  if (k) {
    ev.preventDefault();
    game.input[k] = false;
  }
});

window.addEventListener('mousedown', unlockAudio);

// ------------------------------------------------------------- render

function present() {
  const pal = game.gpal;
  for (let c = 0; c < 256; c++) {
    const l = c * 4, p = c * 3;
    lut[l] = pal[p];
    lut[l + 1] = pal[p + 1];
    lut[l + 2] = pal[p + 2];
    lut[l + 3] = 255;
  }
  const px = game.px;
  const d = img.data;
  for (let i = 0; i < W * H; i++) {
    const l = px[i] << 2;
    const o = i << 2;
    d[o] = lut[l];
    d[o + 1] = lut[l + 1];
    d[o + 2] = lut[l + 2];
    d[o + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
}

// ------------------------------------------------------------- boot

async function boot() {
  const glb1 = await new GLB('data/FILE0001.GLB').load();
  const glb0 = await new GLB('data/FILE0000.GLB').load();
  sound = new Sound(glb0);
  game = new Game(glb1, glb0, sound);

  const r = window.__raptor;
  r.wave = game.wave + 1;

  let acc = 0;
  let last = performance.now();
  let lastState = game.state;

  function tick(now) {
    acc += now - last;
    last = now;
    if (acc > 200) acc = 200; // tab was hidden: don't fast-forward

    while (acc >= FRAME_MS) {
      acc -= FRAME_MS;
      if (game.state === 'playing') game.frame();
      if (game.state !== lastState) {
        lastState = game.state;
        if (game.state !== 'playing') game.drawEndScreen();
      }
    }

    present();
    game.syncRaptor(window.__raptor);
    requestAnimationFrame(tick);
  }

  requestAnimationFrame(tick);
}

boot().catch((err) => {
  console.error('Raptor boot failed:', err);
  const c = document.createElement('div');
  c.textContent = 'Boot failed: ' + err.message;
  c.style.cssText = 'color:#f55;font:14px monospace;margin:2em;';
  document.body.appendChild(c);
});

